// Generated by the build. Caches the app so it starts without network.
const CACHE = 'topside-79b34aa26e4a';
const FILES = ["./","./assets/MapPage-BJkimr48.css","./assets/MapPage-YkJym2A9.js","./assets/ShareCard-BZYTJD3o.js","./assets/ShareCard-CQBcP9yd.css","./assets/StatsPage-BvTlrwrK.js","./assets/StatsPage-CS47HI9b.css","./assets/anton-latin-400-normal-Byf51wtH.woff2","./assets/archivo-black-latin-400-normal-BTVu2TQR.woff2","./assets/bangers-latin-400-normal-DeHY8Ncq.woff2","./assets/bebas-neue-latin-400-normal-9mHNbWWO.woff2","./assets/comic-neue-latin-700-italic-Dsy8JVpH.woff2","./assets/comic-neue-latin-700-normal-NE4Vcoll.woff2","./assets/git-load-C8YQiiqL.js","./assets/help-B22Ko7xw.js","./assets/help-DR-YbZ47.css","./assets/kanit-latin-800-italic-CViYSe9y.woff2","./assets/kanit-latin-800-normal-Bmaevg4i.woff2","./assets/leaflet-src-Cwq2at8A.js","./assets/main-BBMXw6sv.css","./assets/main-x-lPAUOR.js","./assets/modulepreload-polyfill-P2Xu9kJm.js","./assets/pacifico-latin-400-normal-7HIToT7q.woff2","./assets/righteous-latin-400-normal-DIzXvQUm.woff2","./assets/rolldown-runtime-WkwZ5CU-.js","./assets/units-CSfDc_AL.js","./help.html","./icon-192.png","./icon-512.png","./icon-maskable-512.png","./icon.svg","./manifest.webmanifest"];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  // The previous version stays: a page still open with it may load its files later (the map
  // loads Leaflet on demand), also offline. Older ones go. keys() lists caches oldest first.
  event.waitUntil(
    caches
      .keys()
      .then((keys) => keys.filter((k) => k.startsWith('topside-') && k !== CACHE).slice(0, -1))
      .then((old) => Promise.all(old.map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

/** The cached copy of a page; the app's start page for anything else. */
const cachedPage = (request) =>
  caches.match(request, { ignoreSearch: true }).then((hit) => hit || caches.match(new URL('./', self.registration.scope)));

self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin || url.pathname.includes('git-proxy')) return;
  if (request.mode === 'navigate') {
    // Network first for the pages (app, help), so updates arrive. A slow connection (boat, hotel
    // Wi-Fi) gets three seconds, then the cached copy answers; offline it answers at once.
    event.respondWith(
      (async () => {
        const network = fetch(request);
        network.catch(() => undefined); // answered from the cache meanwhile
        const late = new Promise((resolve) => setTimeout(resolve, 3000, null));
        try {
          const response = await Promise.race([network, late]);
          if (response) return response;
        } catch {
          // offline
        }
        return (await cachedPage(request)) || network;
      })(),
    );
    return;
  }
  event.respondWith(caches.match(request).then((hit) => hit || fetch(request)));
});
